def transform(grid):
    # Recolor each monochrome 1-shaped object with its seed color, by comparing
    # its shape to the seed-marked objects in the grid.
    from collections import deque, Counter
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==1 and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); cells=[]
          while q:
            y,x=q.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=y+dy,x+dx
              if 0<=a<h and 0<=b<w and grid[a][b]==1 and (a,b) not in seen:
                seen.add((a,b));q.append((a,b))
          comps.append(cells)
    # Markers are non-1 colors surrounded by the 1 shape. Determine template
