    seeds=[]
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v not in (0,1):
          # component containing neighboring 1 pixels, using marker as a hole
          cand=[]
          for i,co in enumerate(comps):
            if any(abs(y-r)+abs(x-c)==1 for y,x in co): cand.append(i)
          if cand:
            seeds.append((v,cand[0],(r,c)))
    # For each component compute normalized binary mask; seed component colored
    # marker's own cell. Find exact geometrical congruent instances.
    def norm(cells):
      a=min(y for y,x in cells); b=min(x for y,x in cells)
      return frozenset((y-a,x-b) for y,x in cells)
    for color,idx,pos in seeds:
      base=comps[idx]
      # same shape copies; seed object's marker is in missing/overlaid cell
      shape=norm(base)
      for co in comps:
